    has_h = 'h' in s
    has_m = 'm' in s

    hours = 0
    minutes = 0

    if has_h and has_m:
        parts = s.replace('h', ' ').replace('m', ' ').split()
        hours = int(parts[0])
        minutes = int(parts[1])
        return hours * 60 + minutes
    elif has_h:
        return int(s.replace('h', ''))
    elif has_m:
        return int(s.replace('m', ''))
    return 0

