import re


def word_count(s):
    """Count words separated by whitespace or hyphens."""
    if not s or not s.strip():
        return 0
    # Split on whitespace and hyphens
    words = re.split(r'[\s\-]+', s.strip())
    # Filter out any empty strings
    words = [w for w in words if w]
    return len(words)

