def slugify(s):
    """Slugify a string: lowercase, replace each non-alphanumeric char with '-', strip edges."""
    s = s.lower()
    result = []
    for ch in s:
        if ch.isalnum():
            result.append(ch)
        else:
            result.append('-')
    s = ''.join(result)
    s = s.strip('-')
    return s

