import math


def round_half(x: float) -> int:
    """Round x to the nearest integer.

    For positive numbers: round half to even (banker's rounding).
    For negative numbers: round half away from zero.
    """
    if x == math.floor(x):
        return int(x)

    if x > 0:
        # Round half to even for positive numbers
        floor_val = math.floor(x)
        frac = x - floor_val
        if frac > 0.5:
            return int(floor_val + 1)
        elif frac < 0.5:
            return int(floor_val)
        else:
            # Exactly 0.5 - round to even
            if floor_val % 2 == 0:
                return int(floor_val)
            else:
                return int(floor_val + 1)
    else:
        # Round half away from zero for negative numbers
        return int(math.ceil(x - 0.5))

