def parse_duration(s):
    hours = 0
    minutes = 0
    has_h = False
    has_m = False

    i = 0
    while i < len(s):
        if s[i] == 'h':
            has_h = True
            i += 1
        elif s[i] == 'm':
            has_m = True
            i += 1
        elif s[i].isdigit():
            num = ''
            while i < len(s) and s[i].isdigit():
                num += s[i]
                i += 1
            if has_h and not has_m:
                minutes = int(num)
                has_m = True
            elif has_h:
                minutes = int(num)
            elif not has_h:
                if has_m:
                    minutes = int(num)
                else:
                    # Could be hours or minutes depending on what comes next
                    # Peek ahead
                    if i < len(s) and s[i] == 'h':
                        hours = int(num)
                    elif i < len(s) and s[i] == 'm':
                        minutes = int(num)
                    else:
                        minutes = int(num)
            else:
                hours = int(num)
        else:
            i += 1

    if has_h and has_m:
        return hours * 60 + minutes
    elif has_h:
        return hours
    elif has_m:
        return minutes
    return 0

