def caesar(s: str, k: int) -> str:
    """Shift each ASCII letter k places forward, wrapping around and preserving case.
    All other characters are left unchanged."""
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            result.append(chr((ord(ch) - ord('a') + k) % 26 + ord('a')))
        elif 'A' <= ch <= 'Z':
            result.append(chr((ord(ch) - ord('A') + k) % 26 + ord('A')))
        else:
            result.append(ch)
    return ''.join(result)

